"""The EPT matrix-method kernel matrices from the tables generated by ``tools/pt_autogen``
(``tables/ept/matrix_<22|13|uv>.dat``).

A P22 block is ``R(nu1, nu2) I(nu1, nu2)`` and a P13 block ``R(nu1) tan(pi nu1) / pi``.  ``R``
is stored as a constant times a product of integer polynomial factors (positive powers in
the numerator, negative in the denominator), evaluated with numpy by Horner's rule.  Block names and the
conventions are stated in the headers of the tables.
"""
import os
from functools import lru_cache

import numpy as np
from scipy.special import loggamma

from .table_text import fraction, records

TABLE_DIR = os.path.join(os.path.dirname(__file__), 'tables', 'ept')
N_NU = {'22': 2, '13': 1}
"""The number of variables (nu1, nu2 for 22, nu1 for 13) of the polynomial factors."""


def get_I(nu1, nu2):
    log_i = (
        -np.log(8 * np.pi**(3/2))
        + loggamma(3/2 - nu1)
        + loggamma(3/2 - nu2)
        + loggamma(nu1 + nu2 - 3/2)
        - loggamma(nu1)
        - loggamma(nu2)
        - loggamma(3 - nu1 - nu2)
    )
    return np.exp(log_i)


def _horner(coeffs, nu1, nu2=None):
    """``sum_i nu1^i sum_j coeffs[i, j] nu2^j`` (``sum_i coeffs[i] nu1^i`` for 1-d ``coeffs``):
    Horner's rule in nu1, then in nu2."""
    out = 0.0
    for row in coeffs[::-1]:
        if coeffs.ndim == 1:
            inner = row
        else:
            inner = 0.0
            for c in row[::-1]:
                inner = inner * nu2 + c
        out = out * nu1 + inner
    return out


def _matrix_table(prefix):
    """``(names, blocks, factors)`` of tables/ept/matrix_<prefix>.dat (``_tables``)."""
    nv = N_NU[prefix]
    lines = records(os.path.join(TABLE_DIR, f'matrix_{prefix}.dat'))
    consts = {r[1]: float(fraction(r[2])) for r in lines if r[0] == 'block'}
    powers = {b: [] for b in consts}        # block -> [power of the factor f = 0, 1, ..]
    coefficients = {}                       # (block, f) -> {exponents of nu: coefficient}
    for r in lines:
        if r[0] == 'factor':
            powers[r[1]].append(int(r[3]))
        elif r[0] == 'term':
            coefficients.setdefault((r[1], int(r[2])), {})[tuple(int(e) for e in r[3:3 + nv])] = float(fraction(r[3 + nv]))
    blocks, index, factors = [], {}, []
    for b, const in consts.items():
        flist = []
        for f, power in enumerate(powers[b]):
            terms = coefficients[(b, f)]
            coeffs = np.zeros(tuple(1 + max(e[d] for e in terms) for d in range(nv)))
            for e, c in terms.items():
                coeffs[e] = c
            key = (coeffs.shape, coeffs.tobytes())
            if key not in index:          # a factor shared by several blocks is one array
                index[key] = len(factors)
                factors.append(coeffs)
            flist.append((index[key], power))
        blocks.append((const, flist))
    return tuple(consts), blocks, factors


@lru_cache(maxsize=None)
def _tables():
    """``{'22' | '13': (names, blocks, factors), 'uv': array}`` of tables/ept/matrix_<22|13|uv>.dat.

    ``blocks[i] = (const, [(factor index, power)])`` in the order f of the factors of block i;
    ``factors`` are the distinct polynomial factors (coefficient arrays ``[i, j]`` of nu1^i nu2^j,
    ``[i]`` of nu1^i for 13, without zero padding).  ``uv`` is ``(nterms, 7)``, the powers of
    (mu, f, b1, b2, bG2, bGamma3) and the coefficient of each monomial of ``Z1 Z3_UV``.
    """
    out = {prefix: _matrix_table(prefix) for prefix in ('22', '13')}
    path = os.path.join(TABLE_DIR, 'matrix_uv.dat')
    lines = records(path)
    out['uv'] = np.array([[float(int(e)) for e in r[1:7]] + [float(fraction(r[7]))] for r in lines])
    return out


def block_names(prefix):
    """Names of the blocks ``prefix`` ('22' or '13'), sorted as strings."""
    return list(_tables()[prefix][0])


def evaluate(prefix, names, *nu):
    """Kernel matrices of the blocks ``names`` at the numpy arrays ``nu``.

    ``prefix`` '22': ``R(nu1, nu2) I(nu1, nu2)`` at ``nu = (nu1, nu2)``; '13':
    ``R(nu1) tan(pi nu1) / pi`` at ``nu = (nu1,)``.  Each distinct factor and the outer
    function are evaluated once.
    """
    all_names, blocks, factors = _tables()[prefix]
    outer = get_I(*nu) if prefix == '22' else np.tan(np.pi * nu[0]) / np.pi
    values = {}
    out = []
    for name in names:
        const, flist = blocks[all_names.index(name)]
        num, den = const, 1.0
        for j, power in flist:
            if j not in values:
                values[j] = _horner(factors[j], *nu)
            for _ in range(abs(power)):
                if power > 0:
                    num = num * values[j]
                else:
                    den = den * values[j]
        out.append(num / den * outer)
    return out


def uv_table():
    """``(nterms, 7)`` monomials of ``Z1 Z3_UV``: powers of (mu, f, b1, b2, bG2, bGamma3) and the
    coefficient, sorted by the powers of (mu, f, b1).

    ``Z1 = b1 + f mu^2``, ``Z3_UV = -61/315 b1 + ((-3/5 + 2/105 b1) f + (-16/35 - 1/3 b1) f^2) mu^2
    + (-46/105 f^2 - 1/3 f^3) mu^4``.
    """
    return _tables()['uv'].copy()
